#!/usr/bin/env bash
# Terminal theme tests: the yazi and Kitty themes scripts/theme.py generates, and how they touch your config files.
# Usage: tests/terminal-themes.sh     Runs in a throwaway home folder; your real config is never read or written.
# Kitty and yazi are used to check the generated files when they are installed (those checks are skipped otherwise).
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
pass=0; failn=0; skipn=0
ok()   { pass=$((pass+1)); printf '  \033[32mPASS\033[0m %s\n' "$*"; }
bad()  { failn=$((failn+1)); printf '  \033[31mFAIL\033[0m %s\n' "$*"; }
skip() { skipn=$((skipn+1)); printf '  \033[33mSKIP\033[0m %s\n' "$*"; }
check() { if eval "$2"; then ok "$1"; else bad "$1  [$2]"; fi; }

SANDBOX="$(mktemp -d)"; trap 'rm -rf "$SANDBOX"' EXIT
export HOME="$SANDBOX/home" XDG_CONFIG_HOME="$SANDBOX/home/.config" XDG_STATE_HOME="$SANDBOX/home/.local/state"
mkdir -p "$HOME" "$SANDBOX/fakebin"
# theme.py signals running Kitty windows to reload: the tests must not poke your real ones
printf '#!/bin/sh\nexit 1\n' > "$SANDBOX/fakebin/pkill"; chmod 755 "$SANDBOX/fakebin/pkill"; export PATH="$SANDBOX/fakebin:$PATH"
CFG="$XDG_CONFIG_HOME"; KCONF="$CFG/kitty/kitty.conf"; KTHEME="$CFG/kitty/jellyface-theme.conf"; YTHEME="$CFG/yazi/theme.toml"
theme() { python3 "$ROOT/scripts/theme.py" "$@" >/dev/null 2>"$SANDBOX/err"; }
apply_palette() {   # what a palette change does: write_scheme() with a scheme that differs from the last one
    python3 -I -c 'import sys, json; sys.path.insert(0, sys.argv[1]); import theme
s = json.load(open(sys.argv[1] + "/../config/scheme.json")); s["colours"]["background"] = sys.argv[2]
theme.update_cosmic_theme = lambda: None; theme.sync_greeter = lambda: None; theme.write_scheme(s)' "$ROOT/scripts" "$1"
}

echo "opt-in: a palette change never creates theme files"
mkdir -p "$CFG/kitty" "$CFG/yazi"; printf 'font_size 13\n' > "$KCONF"
apply_palette 101010
check "no Kitty theme without setup" '[ ! -e "$KTHEME" ]'
check "kitty.conf untouched without setup" '[ "$(cat "$KCONF")" = "font_size 13" ]'
check "no yazi theme without setup" '[ ! -e "$YTHEME" ]'

echo "setup"
theme terminals --setup; rc=$?
check "theme.py terminals --setup succeeds" '[ $rc -eq 0 ] || { cat "$SANDBOX/err"; false; }'
check "Kitty theme written" '[ -s "$KTHEME" ]'
check "yazi theme written" '[ -s "$YTHEME" ]'
check "kitty.conf keeps its own settings" 'grep -qx "font_size 13" "$KCONF"'
check "kitty.conf includes the theme once" '[ "$(grep -cx "include jellyface-theme.conf" "$KCONF")" -eq 1 ]'
theme terminals --setup
check "setup again: still one include" '[ "$(grep -cx "include jellyface-theme.conf" "$KCONF")" -eq 1 ]'
check "yazi separators are the rounded Nerd Font caps" 'grep -q "sep_left  = { open = \"$(printf "")\"" "$YTHEME"'

echo "palette changes follow"
apply_palette 123456
check "Kitty background follows the palette" 'grep -qix "background #123456" "$KTHEME"'
check "yazi theme regenerated" 'grep -q "Generated by JellyFace" "$YTHEME"'
check "palette change adds no second include" '[ "$(grep -cx "include jellyface-theme.conf" "$KCONF")" -eq 1 ]'

echo "your own edits win"
sed -i 1d "$KTHEME"; cp "$KTHEME" "$SANDBOX/mine"
sed -i 1d "$YTHEME"; cp "$YTHEME" "$SANDBOX/mine-yazi"
apply_palette 654321; theme terminals --setup
check "edited Kitty theme left alone" 'cmp -s "$KTHEME" "$SANDBOX/mine"'
check "edited yazi theme left alone" 'cmp -s "$YTHEME" "$SANDBOX/mine-yazi"'
check "unknown option is refused" '! theme terminals --bogus'

echo "readable colours"
rm -f "$KTHEME"; theme terminals --setup
check "colours 1-7 and 9-15 reach 4.5:1, colour 8 reaches 3:1 on the background" 'python3 -I - "$ROOT/scripts" "$KTHEME" <<'"'"'PY'"'"'
import sys; sys.path.insert(0, sys.argv[1]); import theme
c = dict(l.split() for l in open(sys.argv[2]) if l[:1].isalpha())
bg = theme.hex_to_rgb(c["background"])
low = [i for i in range(1, 16) if theme.contrast(theme.hex_to_rgb(c[f"color{i}"]), bg) < (3 if i == 8 else 4.5) - 0.01]
sys.exit(1 if low else 0)
PY'

echo "the generated files load"
if command -v kitty >/dev/null; then
    check "Kitty parses kitty.conf with the theme" 'kitty +runpy "from kitty.config import load_config; import sys; o = load_config(sys.argv[-1]); sys.exit(0 if o.background else 1)" "$KCONF" >/dev/null 2>&1'
else skip "Kitty not installed"; fi
if command -v yazi >/dev/null && command -v script >/dev/null; then
    cp "$ROOT/config/yazi/yazi.toml" "$CFG/yazi/"
    # yazi reports config errors on screen and keeps running: a clean start runs until the timeout (exit 124)
    TERM=xterm-256color timeout 4 script -qec "stty rows 30 cols 120; yazi $SANDBOX" "$SANDBOX/yazi.log" >/dev/null 2>&1; rc=$?
    check "yazi starts with the config and theme (no errors)" '[ $rc -eq 124 ] && ! grep -aqiE "error at line|failed to parse" "$SANDBOX/yazi.log"'
else skip "yazi or script(1) not installed"; fi

echo "magick stand-in"
if command -v convert >/dev/null; then
    shim="$SANDBOX/bin/magick"; mkdir -p "$SANDBOX/bin"
    sed -n "/<<'SH'/,/^SH\$/p" "$ROOT/scripts/yazi.sh" | sed '1d;$d' > "$shim"; chmod 755 "$shim"
    convert -size 32x24 xc:'#336699' "$SANDBOX/in.png"
    PATH="$SANDBOX/bin:$PATH" timeout 20 "$shim" -limit thread 1 "$SANDBOX/in.png[0]" -auto-orient -strip -filter lanczos -thumbnail '16x16>' \
        -quality 90 "WEBP:$SANDBOX/out.webp" 2>/dev/null
    check "stand-in runs yazi's arguments through ImageMagick 6" '[ "$(identify -format %m "$SANDBOX/out.webp" 2>/dev/null)" = WEBP ]'
    # two stand-ins on PATH (e.g. one in ~/.local/bin and one elsewhere) used to hand over to each other forever
    mkdir -p "$SANDBOX/bin2"; cp "$shim" "$SANDBOX/bin2/magick"
    PATH="$SANDBOX/bin:$SANDBOX/bin2:$PATH" timeout 10 "$shim" "$SANDBOX/in.png" "$SANDBOX/out2.png" 2>/dev/null; rc=$?
    check "two stand-ins on PATH do not loop" '[ $rc -eq 0 ] && [ -s "$SANDBOX/out2.png" ]'
    if [ ! -e /usr/bin/magick ]; then   # a real `magick` after the stand-in gets the work
        printf '#!/bin/sh\necho real "$@"\n' > "$SANDBOX/bin2/magick"
        check "a real magick on PATH is preferred" '[ "$(PATH="$SANDBOX/bin:$SANDBOX/bin2:$PATH" timeout 10 "$shim" x)" = "real x" ]'
    fi
else skip "ImageMagick not installed"; fi

printf '\n%d passed, %d failed, %d skipped\n' "$pass" "$failn" "$skipn"
[ "$failn" -eq 0 ]
